// INPUT:  versioned guest setjmp/longjmp and AAPCS64 registers
// OUTPUT:  rudroid_jump_register_probe validates every GP/FP callee-saved register and SP
// POS:    exercises real guest assembly while preserving the host caller frame
.text
.p2align 2
.global rudroid_jump_register_probe
.type rudroid_jump_register_probe,%function
rudroid_jump_register_probe:
    hint #34
    sub sp,sp,#512
    stp x18,x19,[sp,#0]
    stp x20,x21,[sp,#16]
    stp x22,x23,[sp,#32]
    stp x24,x25,[sp,#48]
    stp x26,x27,[sp,#64]
    stp x28,x29,[sp,#80]
    str x30,[sp,#96]
    stp d8,d9,[sp,#112]
    stp d10,d11,[sp,#128]
    stp d12,d13,[sp,#144]
    stp d14,d15,[sp,#160]
    mov x18,#4626
    mov x19,#4883
    mov x20,#5140
    mov x21,#5397
    mov x22,#5654
    mov x23,#5911
    mov x24,#6168
    mov x25,#6425
    mov x26,#6682
    mov x27,#6939
    mov x28,#7196
    mov x29,#7453
    mov x9,#2056
    fmov d8,x9
    mov x9,#2313
    fmov d9,x9
    mov x9,#2570
    fmov d10,x9
    mov x9,#2827
    fmov d11,x9
    mov x9,#3084
    fmov d12,x9
    mov x9,#3341
    fmov d13,x9
    mov x9,#3598
    fmov d14,x9
    mov x9,#3855
    fmov d15,x9
    add x0,sp,#224
    bl setjmp
    cbnz w0,.Lcheck_jump_registers
    mov x18,#0
    mov x19,#0
    mov x20,#0
    mov x21,#0
    mov x22,#0
    mov x23,#0
    mov x24,#0
    mov x25,#0
    mov x26,#0
    mov x27,#0
    mov x28,#0
    mov x29,#0
    fmov d8,xzr
    fmov d9,xzr
    fmov d10,xzr
    fmov d11,xzr
    fmov d12,xzr
    fmov d13,xzr
    fmov d14,xzr
    fmov d15,xzr
    add x0,sp,#224
    sub sp,sp,#64
    mov w1,#17
    bl longjmp
.Lcheck_jump_registers:
    cmp w0,#17
    b.ne .Lbad_jump_registers
    mov x9,#4626
    cmp x18,x9
    b.ne .Lbad_jump_registers
    mov x9,#4883
    cmp x19,x9
    b.ne .Lbad_jump_registers
    mov x9,#5140
    cmp x20,x9
    b.ne .Lbad_jump_registers
    mov x9,#5397
    cmp x21,x9
    b.ne .Lbad_jump_registers
    mov x9,#5654
    cmp x22,x9
    b.ne .Lbad_jump_registers
    mov x9,#5911
    cmp x23,x9
    b.ne .Lbad_jump_registers
    mov x9,#6168
    cmp x24,x9
    b.ne .Lbad_jump_registers
    mov x9,#6425
    cmp x25,x9
    b.ne .Lbad_jump_registers
    mov x9,#6682
    cmp x26,x9
    b.ne .Lbad_jump_registers
    mov x9,#6939
    cmp x27,x9
    b.ne .Lbad_jump_registers
    mov x9,#7196
    cmp x28,x9
    b.ne .Lbad_jump_registers
    mov x9,#7453
    cmp x29,x9
    b.ne .Lbad_jump_registers
    fmov x9,d8
    cmp x9,#2056
    b.ne .Lbad_jump_registers
    fmov x9,d9
    cmp x9,#2313
    b.ne .Lbad_jump_registers
    fmov x9,d10
    cmp x9,#2570
    b.ne .Lbad_jump_registers
    fmov x9,d11
    cmp x9,#2827
    b.ne .Lbad_jump_registers
    fmov x9,d12
    cmp x9,#3084
    b.ne .Lbad_jump_registers
    fmov x9,d13
    cmp x9,#3341
    b.ne .Lbad_jump_registers
    fmov x9,d14
    cmp x9,#3598
    b.ne .Lbad_jump_registers
    fmov x9,d15
    cmp x9,#3855
    b.ne .Lbad_jump_registers
    mov w0,#0
    b .Lrestore_jump_caller
.Lbad_jump_registers:
    mov w0,#10
.Lrestore_jump_caller:
    ldp d8,d9,[sp,#112]
    ldp d10,d11,[sp,#128]
    ldp d12,d13,[sp,#144]
    ldp d14,d15,[sp,#160]
    ldp x18,x19,[sp,#0]
    ldp x20,x21,[sp,#16]
    ldp x22,x23,[sp,#32]
    ldp x24,x25,[sp,#48]
    ldp x26,x27,[sp,#64]
    ldp x28,x29,[sp,#80]
    ldr x30,[sp,#96]
    add sp,sp,#512
    ret
.size rudroid_jump_register_probe,.-rudroid_jump_register_probe
.section .note.GNU-stack,"",%progbits
